// Les prix viennent UNIQUEMENT de ce catalogue : le navigateur n'envoie que l'id et la quantitÃ©.
// Doit rester alignÃ© avec la liste `products` de script.js.
const CATALOG = {
  1: { name: "L'Ombre", price: 350 },
  2: { name: 'Ã‰clipse', price: 420 },
  3: { name: 'Soleil Noir', price: 380 },
  4: { name: 'Horizon', price: 290 },
  5: { name: 'Mirage', price: 450 },
  6: { name: 'ZÃ©nith', price: 520 },
};
const MAX_QUANTITY = 10;
const SITE = 'https://franck93-sel.github.io/sunglasses-shop/';
// Retours Stripe autorisÃ©s : le site en ligne et le dÃ©veloppement local.
const ALLOWED_RETURN = /^(https:\/\/franck93-sel\.github\.io\/sunglasses-shop\/|http:\/\/(localhost|127\.0\.0\.1)(:\d+)?\/)/;

const input = $input.first().json;
const body = input.body || input;
const items = Array.isArray(body.items) ? body.items : [];

if (items.length === 0 || items.length > 20) {
  throw new Error('Panier vide ou invalide.');
}

// Anciens paniers (avant l'envoi de l'id) : on retrouve le produit par son nom, jamais par son prix.
function findProduct(item) {
  const byId = CATALOG[Number(item.id)];
  if (byId) return byId;
  return Object.values(CATALOG).find((p) => p.name === item.name);
}

const params = [];
function addParam(key, value) {
  params.push(encodeURIComponent(key) + '=' + encodeURIComponent(value));
}

items.forEach((item, idx) => {
  const product = findProduct(item);
  if (!product) throw new Error('Produit inconnu dans le panier.');
  const quantity = item.quantity === undefined ? 1 : Number(item.quantity);
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QUANTITY) {
    throw new Error('QuantitÃ© invalide dans le panier.');
  }
  addParam(`line_items[${idx}][price_data][currency]`, 'eur');
  addParam(`line_items[${idx}][price_data][unit_amount]`, product.price * 100);
  addParam(`line_items[${idx}][price_data][product_data][name]`, product.name);
  addParam(`line_items[${idx}][quantity]`, quantity);
});

function returnUrl(url, fallback) {
  return typeof url === 'string' && ALLOWED_RETURN.test(url) ? url : fallback;
}

addParam('mode', 'payment');
addParam('success_url', returnUrl(body.successUrl, SITE + 'checkout-success.html'));
addParam('cancel_url', returnUrl(body.cancelUrl, SITE + 'checkout.html'));

if (typeof body.email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) {
  addParam('customer_email', body.email.trim());
}

return [{ json: { bodyString: params.join('&') } }];
